"use client";
import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";
import dynamic from "next/dynamic";
import type { Stage } from "@/lib/story/camera";
import { createControls } from "@/lib/story/controls";
import { playhead, type BeatBox, type Playhead } from "@/lib/story/timeline";
import { useReducedMotion } from "./use-reduced-motion";
import { useWebGLSupported } from "./use-webgl-supported";
import { useLook } from "./use-look";
import { WebGLBoundary } from "./webgl-boundary";
import { LookSwitch } from "./look-switch";
import { ChapterRail } from "./rail";
import { Overlay } from "./overlay";
import { Meter } from "./meter";
import { ControlsProvider } from "./controls";
import { checkBundle } from "./validate";
import type { StoryBundle } from "./types";
const Scene = dynamic(() => import("./scene"), { ssr: false });

export function Story({ bundle, children }: { bundle: StoryBundle; children: ReactNode }) {
  const issues = useMemo(() => checkBundle(bundle), [bundle]);
  if (issues.length) throw new Error(`Invalid story: ${issues.join("; ")}`);
  const rootRef = useRef<HTMLDivElement>(null);
  const headRef = useRef<Playhead>({ beat: 0, dwell: 0 });
  const stageRef = useRef<Stage>({ viewport: 0, header: 0, captions: [] });
  const pointerRef = useRef({ x: 0, y: 0 });
  const fpsRef = useRef(0);
  const [controls] = useState(createControls);
  const webgl = useWebGLSupported();
  const still = useReducedMotion();
  const [failed, setFailed] = useState(false);
  const [running, setRunning] = useState(true);
  const [activeChapter, setActiveChapter] = useState<string | undefined>(bundle.story.chapters[0]?.id);
  const onError = useCallback(() => setFailed(true), []);
  const id = useLook(bundle.looks, bundle.defaultLook);
  const look = bundle.looks.find(look => look.id === id) ?? bundle.looks[0];
  const on = webgl === true && !failed;
  const items = useMemo(() => bundle.story.chapters.map(chapter => ({ id: chapter.id, number: chapter.number, label: chapter.name })), [bundle.story]);
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let boxes: BeatBox[] = [];
    const update = () => { headRef.current = playhead(-root.getBoundingClientRect().top, window.innerHeight, boxes); };
    const measure = () => {
      const origin = root.getBoundingClientRect().top;
      const beats = Array.from(root.querySelectorAll<HTMLElement>("[data-beat]"));
      boxes = beats.map(beat => { const box = beat.getBoundingClientRect(); return { top: box.top - origin, height: box.height }; });
      const top = root.querySelector<HTMLElement>("[data-story-top]");
      stageRef.current = { viewport: window.innerHeight, header: top ? top.offsetTop + top.offsetHeight : 0, captions: beats.map(beat => {
        const caption = beat.querySelector<HTMLElement>(".story-caption");
        const text = beat.querySelector<HTMLElement>(".story-caption-text");
        return caption && text ? text.getBoundingClientRect().height + parseFloat(getComputedStyle(caption).paddingBottom) : 0;
      }) };
      update();
    };
    measure();
    const resize = new ResizeObserver(measure);
    resize.observe(root);
    root.querySelectorAll(".story-caption-text").forEach(node => resize.observe(node));
    let visible = true;
    const visibility = () => setRunning(visible && !document.hidden);
    const seen = new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; visibility(); });
    seen.observe(root);
    document.addEventListener("visibilitychange", visibility);
    window.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", measure);
    return () => { resize.disconnect(); seen.disconnect(); window.removeEventListener("scroll", update); window.removeEventListener("resize", measure); document.removeEventListener("visibilitychange", visibility); };
  }, [bundle.story, on]);
  useEffect(() => {
    if (still) { pointerRef.current = { x: 0, y: 0 }; return; }
    const move = (event: PointerEvent) => { if (event.pointerType === "mouse") pointerRef.current = { x: event.clientX / window.innerWidth * 2 - 1, y: 1 - event.clientY / window.innerHeight * 2 }; };
    window.addEventListener("pointermove", move, { passive: true });
    return () => window.removeEventListener("pointermove", move);
  }, [still]);
  const style = { "--story-ground": look.ground, "--story-ink": look.ink, "--story-faint": look.faint, "--story-accent": look.accent } as CSSProperties;
  return <ControlsProvider controls={controls} sceneOff={!on}><div ref={rootRef} className="story" data-scene={on ? "on" : "off"} data-look={look.id} style={style}>
    <noscript><style>{".story-look-switch, .story-control { display: none !important; }"}</style></noscript>
    {on ? <><div className="story-scene" aria-hidden="true"><WebGLBoundary onError={onError}><Scene bundle={bundle} headRef={headRef} stageRef={stageRef} pointerRef={pointerRef} controls={controls} look={look} still={still} running={running} rootRef={rootRef} fpsRef={fpsRef} onError={onError} onChapter={setActiveChapter} /></WebGLBoundary></div><div className="story-rail-holder"><ChapterRail label={bundle.copy.railLabel} items={items} active={activeChapter} /></div><Overlay links={bundle.links ?? []} controls={controls} /></> : null}
    {bundle.looks.length > 1 ? <div className="story-bar"><div data-story-top><LookSwitch looks={bundle.looks} active={look.id} defaultLook={bundle.defaultLook ?? bundle.looks[0].id} label={bundle.copy.lookLabel} /></div></div> : null}
    <div className="story-content">{children}</div><Meter value={fpsRef} label={bundle.copy.fpsLabel} />
  </div></ControlsProvider>;
}
"use client";
import { Suspense, lazy, useEffect, useMemo, useRef, useState, type RefObject } from "react";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { blankFormation } from "@/lib/story/formation";
import type { Stage } from "@/lib/story/camera";
import type { Controls } from "@/lib/story/controls";
import { beatsOf, chapterAt, chapterNear } from "@/lib/story/story";
import { createQuality, type Quality } from "@/lib/story/quality";
import type { Look } from "@/lib/story/looks";
import type { Playhead } from "@/lib/story/timeline";
import { Conductor, newFrame, type Frame } from "./conductor";
import { Pieces, CAMERA_Z, FOV, type Pointer } from "./pieces";
import { Lighting, Floor } from "./stage";
import { ExtraBoundary } from "./extra-frame";
import type { StoryBundle } from "./types";

function Monitor({ bundle, frameRef, onNear, onError, onQuality, onChapter, coarse, fpsRef }: { bundle: StoryBundle; frameRef: RefObject<Frame>; onNear: (near: string) => void; onError: () => void; onQuality: (quality: Quality) => void; onChapter: (chapter: string | undefined) => void; coarse: boolean; fpsRef: RefObject<number> }) {
  const gl = useThree(state => state.gl);
  // Quality remembers the device's budget; each look chooses whether to use it.
  const quality = useRef(createQuality({ dpr: Math.min(window.devicePixelRatio, coarse ? 1.5 : 1.75), shadows: true }));
  const near = useRef(""); const step = useRef(0);
  const chapter = useRef<string | undefined>(undefined);
  useEffect(() => {
    const lost = (event: Event) => { event.preventDefault(); onError(); };
    gl.domElement.addEventListener("webglcontextlost", lost);
    return () => gl.domElement.removeEventListener("webglcontextlost", lost);
  }, [gl, onError]);
  useFrame((_, delta) => {
    if (delta > 0 && !document.hidden) {
      fpsRef.current = fpsRef.current ? fpsRef.current * 0.9 + (1 / delta) * 0.1 : 1 / delta;
      const next = quality.current.sample(Math.min(delta * 1000, 250));
      if (next.step !== step.current) { step.current = next.step; onQuality(next); }
    }
    const value = (bundle.extras ?? []).map((extra, index) => chapterNear(bundle.story, extra.chapter, frameRef.current.beat, 0.5) ? index : "").filter(String).join(",");
    if (value !== near.current) { near.current = value; onNear(value); }
    const current = chapterAt(bundle.story, frameRef.current.beat);
    if (current !== chapter.current) { chapter.current = current; onChapter(current); }
  });
  return null;
}
export default function Scene({ bundle, headRef, stageRef, pointerRef, controls, look, still, running, rootRef, fpsRef, onError, onChapter }: { bundle: StoryBundle; headRef: RefObject<Playhead>; stageRef: RefObject<Stage>; pointerRef: RefObject<Pointer>; controls: Controls; look: Look; still: boolean; running: boolean; rootRef: RefObject<HTMLDivElement | null>; fpsRef: RefObject<number>; onError: () => void; onChapter: (chapter: string | undefined) => void }) {
  const frameRef = useRef(newFrame(bundle.story.pieces));
  const formationRef = useRef(blankFormation(bundle.story.pieces));
  const [coarse] = useState(() => window.matchMedia("(pointer: coarse)").matches);
  const [quality, setQuality] = useState<Quality>(() => ({ dpr: Math.min(window.devicePixelRatio, coarse ? 1.5 : 1.75), shadows: true, step: 0 }));
  const [near, setNear] = useState("");
  const extras = useMemo(() => (bundle.extras ?? []).map(extra => ({ ...extra, Component: lazy(extra.load) })), [bundle.extras]);
  const active = near ? near.split(",").map(Number) : [];
  return <Canvas shadows={quality.shadows && look.shadows} dpr={quality.dpr} camera={{ fov: FOV, position: [0, 0, CAMERA_Z] }} frameloop={running ? "always" : "never"}>
    <Conductor headRef={headRef} frameRef={frameRef} still={still} beats={beatsOf(bundle.story).length} />
    <Monitor bundle={bundle} frameRef={frameRef} onNear={setNear} onError={onError} onQuality={setQuality} onChapter={onChapter} coarse={coarse} fpsRef={fpsRef} />
    <Lighting look={look} />
    <Pieces key={look.id} bundle={bundle} frameRef={frameRef} stageRef={stageRef} pointerRef={pointerRef} formationRef={formationRef} controls={controls} look={look} coarse={coarse} still={still} rootRef={rootRef} onError={onError}>
      {extras.map(({ chapter, Component }, index) => <ExtraBoundary key={`${chapter}-${index}`}><Suspense fallback={null}>{active.includes(index) ? <Component frameRef={frameRef} look={look} still={still} controls={controls} /> : null}</Suspense></ExtraBoundary>)}
    </Pieces>
    <Floor look={look} formationRef={formationRef} />
  </Canvas>;
}
import type { CSSProperties, ReactNode } from "react";
import { beatHeight, type StoryDef } from "@/lib/story/story";
export function Chapter({ id, children }: { id: string; children: ReactNode }) {
  return <section id={id} aria-labelledby={`${id}-title`}>{children}</section>;
}
export function Beat({ story, id, children, fallback }: { story: StoryDef; id: string; children: ReactNode; fallback?: ReactNode }) {
  return <div data-beat={id} className="story-beat" style={{ "--beat-height": beatHeight(story, id) } as CSSProperties}>
    <div className="story-caption"><div className="story-caption-text">{children}{fallback ? <div className="story-fallback">{fallback}</div> : null}</div></div>
  </div>;
}
export function Kicker({ number, id, as: Tag = "p", children }: { number: number; id?: string; as?: "p" | "h2"; children: ReactNode }) {
  return <Tag id={id} aria-hidden={Tag === "p" ? true : undefined} className="story-kicker"><span>{number}</span><span aria-hidden> / </span>{children}</Tag>;
}
export function Title({ as: Tag = "h3", id, children }: { as?: "h1" | "h2" | "h3"; id?: string; children: ReactNode }) {
  return <Tag id={id} className="story-title">{children}</Tag>;
}
export function Body({ children }: { children: ReactNode }) { return <p className="story-body">{children}</p>; }
export function Note({ sceneOnly = false, children }: { sceneOnly?: boolean; children: ReactNode }) {
  return <p className={`story-note${sceneOnly ? " story-note-scene" : ""}`}>{children}</p>;
}
import { blankFormation, type BeatFormation, type Formation } from "../lib/story/formation.ts";
import { measure, stack } from "../lib/story/layouts.ts";
import { story, type BeatId } from "./story.ts";

// One sheet that stays where it is; its picture changes with the chapter.
function formation(): Formation {
  const pieces = stack(story.pieces, [1.4, 1.9]), bounds = measure(pieces);
  return {
    ...blankFormation(story.pieces), pieces,
    span: bounds.span * 1.15, rise: bounds.rise * 1.15,
    anchor: [0.42, 0.16], turn: [0.12, -0.12], near: 5,
    floor: -3.5,
  };
}

export const formations = {
  "opening.one": { rest: formation() },
  "middle.one": { rest: formation() },
  "close.one": { rest: formation() },
} satisfies Record<BeatId, BeatFormation>;
export const extras = [{ chapter: "middle", load: () => import("./extras/middle-line") }];
{
  "overlay": {
    "beat": "close.one",
    "selector": ".story-piece-link[data-story-link=\"0\"]"
  },
  "lazyExtra": true
