      { name: `${look}-short`, look, flags: [...expected, "--size=1280x720", "--expect-scene=on", "--late-shaders=40000"] },
      { name: `${look}-phone`, look, flags: [...expected, "--size=390x844", "--touch", "--expect-scene=on"] },
      { name: `${look}-reduced`, look, flags: [...expected, "--size=1440x900", "--reduced-motion", "--expect-scene=on", "--positions=start,mid,end", "--assert-still=300"] },
      { name: `${look}-no-webgl`, look, flags: [...expected, "--size=1440x900", "--no-webgl", "--expect-scene=off"] },
